# Apply the rule: vertical segments of non-bg color that are
# separated by exactly 1 bg row from vertical segments of 2s at the same column
# get transformed to 5

bg = 4
h, w = 28, 17

def find_vertical_segments(grid, color, col):
    """Find contiguous vertical segments at given column"""
    segments = []
    for r in range(h):
        if grid[r][col] == color:
            seg_start = r
            while r + 1 < h and grid[r+1][col] == color:
                r += 1
            segments.append((seg_start, r))
    return segments

# Find all vertical segment pairs (2-segment -> 1-gap -> non-bg segment)
print("=== Finding 2-segments at each column ===")
column_transforms = {}  # col: (seg_to_transform)
for col in range(w):
    # Find 2-segments
    two_segs = find_vertical_segments([row[col] for row in input_grid], 2, col)
    if not two_segs:
        continue

    # Find non-bg (non-4, non-2) segments that are exactly 1 row below
    for two_seg_start, two_seg_end in two_segs:
        gap_col_start = two_seg_end + 1  # Should be the gap row
        gap_col_end = two_seg_end + 1    # Same single row

        non_bg_start = gap_col_end + 1   # After the gap
        non_bg_end = non_bg_start

        # Check if there's a segment of the same column from non_bg_start
        while non_bg_end < h and input_grid[non_bg_end][col] not in [bg, 2]:
            non_bg_end += 1
        non_bg_end -= 1  # Back to last valid

        if non_bg_end >= non_bg_start:
            print(f"  Col {col}: 2-seg {two_seg_start}-{two_seg_end}, gap row {gap_col_start}, non-bg {non_bg_start}-{non_bg_end}")
            segment_cells = [(r, col) for r in range(non_bg_start, non_bg_end + 1)]
            column_transforms[col] = column_transforms.get(col, []) + segment_cells

print("\n=== Segments to transform ===")
for col, cells in column_transforms.items():
    for r, c in cells:
        print(f"  ({r},{c}): {input_grid[r][c]} -> 5")

# Apply the transformation
